-- Oman milestone ES/DE/FR translations (completing 257). INSERT OR IGNORE.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-specs', 'es', 'La Autoridad Tributaria de Omán pone en marcha el programa de facturación electrónica Fawtara', 'La Autoridad Tributaria de Omán (OTA) publicó las especificaciones técnicas de un nuevo programa nacional de facturación electrónica, Fawtara, iniciando un despliegue estructurado hacia la facturación electrónica obligatoria para las empresas registradas a efectos del IVA. Esto siguió a consultas iniciadas el mes anterior y precede a un mandato por fases que se extiende hasta 2028.', '["No se requiere ninguna acción todavía, salvo que la OTA ya haya identificado a su empresa como candidata de la Fase 1 o la Fase 2", "Comience a seguir las comunicaciones de la OTA si su empresa está entre los mayores contribuyentes de Omán por tamaño, volumen de transacciones o sector"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-specs', 'de', 'Omans Steuerbehörde startet das E-Rechnungsprogramm Fawtara', 'Die omanische Steuerbehörde (OTA) veröffentlichte die technischen Spezifikationen für ein neues nationales E-Rechnungsprogramm namens Fawtara und leitete damit einen strukturierten Übergang zur verpflichtenden E-Rechnung für mehrwertsteuerregistrierte Unternehmen ein. Dem gingen im Vormonat begonnene Konsultationen voraus; es folgt eine bis 2028 laufende, gestaffelte Pflicht.', '["Noch keine Maßnahme erforderlich, es sei denn, die OTA hat Ihr Unternehmen bereits als Kandidat für Phase 1 oder Phase 2 identifiziert", "Beginnen Sie mit der Beobachtung der OTA-Mitteilungen, falls Ihr Unternehmen zu Omans größten Steuerpflichtigen nach Größe, Transaktionsvolumen oder Branche zählt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-specs', 'fr', 'L''Autorité fiscale d''Oman lance le programme de facturation électronique Fawtara', 'L''Autorité fiscale d''Oman (OTA) a publié les spécifications techniques d''un nouveau programme national de facturation électronique, Fawtara, amorçant un déploiement structuré vers la facturation électronique obligatoire pour les entreprises immatriculées à la TVA. Cela fait suite à des consultations entamées le mois précédent et précède une obligation par phases s''étalant jusqu''en 2028.', '["Aucune action n''est encore requise, sauf si l''OTA a déjà identifié votre entreprise comme candidate pour la Phase 1 ou la Phase 2", "Commencez à surveiller les communications de l''OTA si votre entreprise compte parmi les plus grands contribuables d''Oman par taille, volume de transactions ou secteur"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-asp', 'es', 'Se abre el registro de Proveedores de Servicios Acreditados (ASP)', 'La OTA abrió su portal de registro en línea para Proveedores de Servicios Acreditados (ASP) — los intermediarios certificados que toda empresa necesitará para emitir y recibir facturas electrónicas bajo el modelo Peppol de cinco esquinas de Fawtara. Esto siguió a la publicación en diciembre de 2025 de los estándares de acreditación de ASP y al lanzamiento en febrero de 2026 de un portal de desarrollador/pruebas.', '["Si ha sido notificado como contribuyente de la Fase 1 o la Fase 2, comience a evaluar y designar un ASP", "Confirme que los datos de contacto de su responsable principal estén actualizados ante la OTA para recibir las notificaciones de fase"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-asp', 'de', 'Registrierung für akkreditierte Dienstanbieter (ASP) startet', 'Die OTA eröffnete ihr Online-Registrierungsportal für akkreditierte Dienstanbieter (Accredited Service Providers, ASP) — die zertifizierten Vermittler, die jedes Unternehmen benötigt, um E-Rechnungen unter Fawtaras Peppol-Fünf-Ecken-Modell auszustellen und zu empfangen. Dem gingen die im Dezember 2025 veröffentlichten ASP-Akkreditierungsstandards und die im Februar 2026 gestartete Entwickler-/Testplattform voraus.', '["Falls als Phase-1- oder Phase-2-Steuerpflichtiger benachrichtigt, beginnen Sie mit der Bewertung und Beauftragung eines ASP", "Bestätigen Sie, dass die Kontaktdaten Ihres Hauptverantwortlichen bei der OTA aktuell sind, damit Phasen-Benachrichtigungen ankommen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-asp', 'fr', 'Ouverture de l''enregistrement des prestataires de services agréés (ASP)', 'L''OTA a ouvert son portail d''enregistrement en ligne pour les prestataires de services agréés (Accredited Service Providers, ASP) — les intermédiaires certifiés dont chaque entreprise aura besoin pour émettre et recevoir des factures électroniques selon le modèle Peppol à cinq coins de Fawtara. Cela fait suite à la publication en décembre 2025 des normes d''agrément des ASP et au lancement en février 2026 d''un portail de développement/test.', '["Si vous avez été notifié en tant que contribuable de Phase 1 ou de Phase 2, commencez à évaluer et à désigner un ASP", "Vérifiez que les coordonnées de votre responsable principal sont à jour auprès de l''OTA afin de recevoir les notifications de phase"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase1', 'es', 'Fase 1 — Los 100 mayores contribuyentes de Omán deben emitir y recibir facturas electrónicas', 'La facturación electrónica obligatoria a través de la plataforma Fawtara entra en vigor para aproximadamente los 100 mayores contribuyentes seleccionados por la OTA, según el tamaño de la empresa, el volumen de transacciones, la diversidad sectorial, la distribución geográfica y el perfil de riesgo. Las empresas fuera de esta primera ola pueden participar voluntariamente. Esta es la primera fase genuinamente vinculante del mandato de facturación electrónica de Omán.', '["Confirme directamente con la OTA si su empresa ha sido seleccionada para la Fase 1", "Si ha sido seleccionada, asegúrese de que su integración con el ASP y sus sistemas ERP estén operativos antes de esta fecha"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase1', 'de', 'Phase 1 — Omans 100 größte Steuerpflichtige müssen E-Rechnungen ausstellen und empfangen', 'Die verpflichtende E-Rechnung über die Fawtara-Plattform tritt für rund 100 der größten von der OTA ausgewählten Steuerpflichtigen in Kraft, basierend auf Unternehmensgröße, Transaktionsvolumen, Branchenvielfalt, geografischer Verteilung und Risikoprofil. Unternehmen außerhalb dieser ersten Welle können freiwillig teilnehmen. Dies ist die erste tatsächlich verbindliche Phase von Omans E-Rechnungspflicht.', '["Bestätigen Sie direkt bei der OTA, ob Ihr Unternehmen für Phase 1 ausgewählt wurde", "Falls ausgewählt, stellen Sie sicher, dass Ihre ASP-Integration und ERP-Systeme vor diesem Datum betriebsbereit sind"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase1', 'fr', 'Phase 1 — Les 100 plus grands contribuables d''Oman doivent émettre et recevoir des factures électroniques', 'La facturation électronique obligatoire via la plateforme Fawtara entre en vigueur pour environ les 100 plus grands contribuables sélectionnés par l''OTA, sur la base de la taille de l''entreprise, du volume de transactions, de la diversité sectorielle, de la répartition géographique et du profil de risque. Les entreprises en dehors de cette première vague peuvent participer volontairement. C''est la première phase véritablement contraignante de l''obligation de facturation électronique d''Oman.', '["Confirmez directement auprès de l''OTA si votre entreprise a été sélectionnée pour la Phase 1", "Si sélectionnée, assurez-vous que votre intégration ASP et vos systèmes ERP sont opérationnels avant cette date"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase2', 'es', 'Fase 2 — El resto de los grandes contribuyentes pasa a ser obligatorio', 'El mandato se amplía a todos los grandes contribuyentes restantes aún no cubiertos por la Fase 1, aproximadamente seis meses después de la entrada en vigor de la Fase 1. Las empresas afectadas fueron notificadas a partir de marzo de 2026 y se les pidió confirmar su preparación técnica mediante una encuesta de la OTA.', '["Compruebe si la OTA ha notificado a su empresa como contribuyente de la Fase 2", "Complete cualquier encuesta de preparación técnica de la OTA antes de su plazo indicado"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase2', 'de', 'Phase 2 — Verbleibende Großsteuerpflichtige werden verpflichtend erfasst', 'Die Pflicht wird auf alle verbleibenden Großsteuerpflichtigen ausgeweitet, die noch nicht von Phase 1 erfasst wurden, rund sechs Monate nach dem Start von Phase 1. Betroffene Unternehmen wurden ab März 2026 benachrichtigt und gebeten, ihre technische Bereitschaft über eine OTA-Umfrage zu bestätigen.', '["Prüfen Sie, ob die OTA Ihr Unternehmen als Phase-2-Steuerpflichtigen benachrichtigt hat", "Füllen Sie eine etwaige OTA-Umfrage zur technischen Bereitschaft fristgerecht aus"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase2', 'fr', 'Phase 2 — Les grands contribuables restants deviennent soumis à l''obligation', 'L''obligation s''étend à tous les grands contribuables restants non encore couverts par la Phase 1, environ six mois après l''entrée en vigueur de la Phase 1. Les entreprises concernées ont été notifiées à partir de mars 2026 et invitées à confirmer leur préparation technique via une enquête de l''OTA.', '["Vérifiez si l''OTA a notifié votre entreprise en tant que contribuable de Phase 2", "Complétez toute enquête de préparation technique de l''OTA avant l''échéance indiquée"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase3', 'es', 'Fase 3 — Todos los demás contribuyentes registrados a efectos del IVA, incluidas las pymes', 'La facturación electrónica obligatoria se extiende a todos los contribuyentes registrados a efectos del IVA que queden en Omán, incluidas las pequeñas y medianas empresas, completando el despliegue B2B nacional aproximadamente un año después del inicio de la Fase 1.', '["Regístrese ante un ASP acreditado por la OTA con suficiente antelación si aún no lo ha hecho", "Presupueste los cambios de ERP o software de facturación si sus sistemas todavía no admiten la salida estructurada UBL 2.1 / PINT-OM"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase3', 'de', 'Phase 3 — Alle verbleibenden mehrwertsteuerregistrierten Steuerpflichtigen, einschließlich KMU', 'Die verpflichtende E-Rechnung wird auf jeden verbleibenden mehrwertsteuerregistrierten Steuerpflichtigen in Oman ausgeweitet, einschließlich kleiner und mittlerer Unternehmen, und schließt damit den inländischen B2B-Rollout rund ein Jahr nach Beginn von Phase 1 ab.', '["Registrieren Sie sich rechtzeitig bei einem OTA-akkreditierten ASP, falls noch nicht geschehen", "Planen Sie ERP- oder Rechnungssoftware-Änderungen ein, falls Ihre Systeme die strukturierte UBL-2.1-/PINT-OM-Ausgabe noch nicht unterstützen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase3', 'fr', 'Phase 3 — Tous les contribuables restants immatriculés à la TVA, y compris les PME', 'La facturation électronique obligatoire s''étend à tout contribuable restant immatriculé à la TVA à Oman, y compris les petites et moyennes entreprises, achevant le déploiement B2B national environ un an après le début de la Phase 1.', '["Inscrivez-vous auprès d''un ASP agréé par l''OTA bien avant cette date si ce n''est pas déjà fait", "Prévoyez un budget pour les changements d''ERP ou de logiciel de facturation si vos systèmes ne prennent pas encore en charge la sortie structurée UBL 2.1 / PINT-OM"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase4-b2g', 'es', 'Fase 4 — La facturación electrónica obligatoria se completa para las transacciones con contrapartes gubernamentales', 'La fase final del despliegue incorpora plenamente a los organismos gubernamentales como contrapartes de facturación electrónica, un año después de la Fase 3, marcando la finalización de la implementación por fases de Fawtara en Omán.', '["Si abastece a organismos gubernamentales omaníes, confirme que su proceso de facturación cubre específicamente las transacciones con contrapartes gubernamentales antes de esta fecha"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase4-b2g', 'de', 'Phase 4 — Verpflichtende E-Rechnung wird für Transaktionen mit staatlichen Gegenparteien abgeschlossen', 'Die letzte Phase des Rollouts bezieht Regierungsstellen ein Jahr nach Phase 3 vollständig als E-Rechnungs-Gegenparteien ein und markiert den Abschluss von Omans gestaffelter Fawtara-Umsetzung.', '["Falls Sie omanische Regierungsstellen beliefern, bestätigen Sie, dass Ihr Rechnungsprozess Transaktionen mit staatlichen Gegenparteien bis zu diesem Datum speziell abdeckt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('om-phase4-b2g', 'fr', 'Phase 4 — La facturation électronique obligatoire s''achève pour les transactions avec des contreparties gouvernementales', 'La dernière phase du déploiement intègre pleinement les organismes gouvernementaux en tant que contreparties de facturation électronique, un an après la Phase 3, marquant l''achèvement de la mise en œuvre échelonnée de Fawtara à Oman.', '["Si vous fournissez des organismes gouvernementaux omanais, confirmez que votre processus de facturation couvre spécifiquement les transactions avec des contreparties gouvernementales avant cette date"]');
